<?php $pageTitle='Customer Login';$theme='pink';require_once 'includes/user-auth.php';$error='';$redirect=$_GET['redirect']??'account.php';if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$q->execute([trim($_POST['email'])]);$u=$q->fetch();if($u&&password_verify($_POST['password'],$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];header('Location: '.($_POST['redirect']?:'account.php'));exit;}$error='Invalid email or password.';}include 'includes/header.php';?><section class="py-5"><div class="col-lg-5 mx-auto"><div class="content-card p-4 p-md-5"><h2>Customer Login</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><input type="hidden" name="redirect" value="<?=htmlspecialchars($redirect)?>"><input name="email" type="email" class="form-control mb-3" placeholder="Email" required><input name="password" type="password" class="form-control mb-3" placeholder="Password" required><button class="btn btn-brand w-100">Login</button></form><p class="mt-3 mb-0">New here? <a href="register.php">Create an account</a></p></div></div></section><?php include 'includes/footer.php';?>
